def squareGaugesEvenKeyCensus(readings, k):
    a=readings
    out=[]
    for x in a:
        left,right=0,x+1
        while left+1<right:
            mid=(left+right)//2
            if mid*mid<=x: left=mid
            else: right=mid
        out.append(left)
    return sum(x%2==0 for x in out)

